 'indexes',(select jsonb_agg(indexdef order by indexname) from pg_indexes where schemaname='public' and tablename=c.relname)) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname='learn_assessment_cancellations'),'ledger',(select jsonb_agg(jsonb_build_object('name',migration_name,'sha256',source_sha256,'project',project_ref) order by migration_name) from of_test_deploy.migrations)),'functions',(select coalesce(jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'definition',pg_get_functiondef(p.oid),'owner',pg_get_userbyid(p.proowner),'acl',p.proacl::text) order by p.oid::regprocedure::text),'[]'::jsonb) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('learn_business_input_time_detail','learn_commusoft_job_details'))))::text) <> 'f380f1bcfc60dd0da7bd99f8822d969d' then raise exception 'Exact Job details prerequisites required';end if;
